//! Generates `apps/web/src/wire/generated/cosmetics.ts` from `cosmetics.json` (#1295, SPEC §11, R1295000, R633),
//! each version's offer as the cards it takes (R2725001), (R3015000) each level's place on its ladder and (R3343000)
//! each card's default look.

use jackioh_server::config::PLAYER_SETTINGS_TEXT_MAX_LENGTH;
use jackioh_server::cosmetics::{CosmeticKind, CosmeticRarity, default_look, offered, shipped, shipped_defs};

/// The generated file, relative to this crate.
const OUTPUT: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../apps/web/src/wire/generated/cosmetics.ts"
);

const HEADER: &str = "// Generated by crates/server/tests/export_cosmetics.rs from crates/shared/cosmetics.json\n// (R1295000). Do not edit: change the registry and run the test.\n\n";

/// One of the registry's values as one line of JSON.
fn json(value: &impl serde::Serialize) -> String {
    serde_json::to_string(value).unwrap_or_else(|error| panic!("cosmetics.json: {error}"))
}

/// The file's text: the header, the kinds, the rarities, the id cap, then one line per entry, then each
/// version's and augment's offered cards, sorted, as `offered` takes them (R2725001), so the client never
/// reads an offer's clauses itself.
fn render() -> String {
    let cosmetics = shipped().unwrap_or_else(|error| panic!("cosmetics.json: {error}"));
    let mut out = String::from(HEADER);
    out.push_str(&format!(
        "export const COSMETIC_KINDS = {} as const;\n",
        json(&CosmeticKind::PICKED)
    ));
    out.push_str(&format!(
        "export const COSMETIC_RARITIES = {} as const;\n",
        json(&CosmeticRarity::ALL)
    ));
    // The cosmetics' own scale, a type of its own so the client cannot take it for a card's
    // rarity (R1333000).
    out.push_str("export type CosmeticRarity = (typeof COSMETIC_RARITIES)[number];\n");
    out.push_str(&format!(
        "export const COSMETIC_ID_MAX_LENGTH = {PLAYER_SETTINGS_TEXT_MAX_LENGTH};\n"
    ));
    out.push_str("export const COSMETICS = [\n");
    for cosmetic in &cosmetics {
        out.push_str(&format!("  {},\n", json(cosmetic)));
    }
    out.push_str("] as const;\n");
    out.push_str("export const COSMETIC_OFFERS: Readonly<Record<string, readonly string[]>> = {\n");
    // R3015000: the levels alone; a retired augment is offered nothing.
    for cosmetic in cosmetics
        .iter()
        .filter(|cosmetic| cosmetic.kind == CosmeticKind::Version)
    {
        let mut cards: Vec<&str> = shipped_defs()
            .keys()
            .map(String::as_str)
            .filter(|card| offered(cosmetic, Some(card)))
            .collect();
        cards.sort_unstable();
        out.push_str(&format!("  {}: {},\n", json(&cosmetic.id), json(&cards)));
    }
    out.push_str("};\n");
    // R3015000: each level's variant, rank and what it adds, so the client reads a ladder without a clause.
    out.push_str(
        "export const COSMETIC_LEVELS: Readonly<Record<string, { readonly variant: string; readonly rank: number; readonly adds: \"art\" | \"fullArt\" | \"animated\" | \"signed\"; readonly defaultOn?: readonly string[] }>> = {\n",
    );
    for (id, level) in cosmetics
        .iter()
        .filter_map(|cosmetic| cosmetic.level.as_ref().map(|level| (&cosmetic.id, level)))
    {
        out.push_str(&format!("  {}: {},\n", json(id), json(level)));
    }
    out.push_str("};\n");
    // R3343000: each card whose Default draws a level's look, tokens by their printed rarity, to that level, so the
    // client never reads a card's rarity against `defaultOn` itself.
    out.push_str("export const COSMETIC_DEFAULT_LOOKS: Readonly<Record<string, string>> = {\n");
    let mut cards: Vec<&str> = shipped_defs().keys().map(String::as_str).collect();
    cards.sort_unstable();
    for card in cards {
        if let Some(look) = default_look(&cosmetics, card) {
            out.push_str(&format!("  {}: {},\n", json(&card), json(&look.id)));
        }
    }
    out.push_str("};\n");
    out
}

#[test]
fn every_entry_is_one_line() {
    let cosmetics = shipped().unwrap_or_else(|error| panic!("cosmetics.json: {error}"));
    assert_eq!(render().matches("\n  {\"id\":").count(), cosmetics.len());
}

#[test]
fn export_cosmetics() {
    let text = render();
    let current = std::fs::read_to_string(OUTPUT).unwrap_or_default();
    if current != text {
        if let Some(parent) = std::path::Path::new(OUTPUT).parent() {
            std::fs::create_dir_all(parent).unwrap_or_else(|error| panic!("{}: {error}", parent.display()));
        }
        std::fs::write(OUTPUT, &text).unwrap_or_else(|error| panic!("{OUTPUT}: {error}"));
    }
}
